// Mélange équitable (Fisher-Yates) — utilisé partout dans l'app
const shuffle = a => {const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;};
// Place la bonne réponse à la position "tgt" et mélange les 3 autres
const placeCorrectAt = (q, tgt) => {
  const wrong = shuffle(q.answers.filter((_, i) => i !== q.correct));
  const na = []; let wi = 0;
  for (let i = 0; i < 4; i++) { if (i === tgt) na.push(q.answers[q.correct]); else na.push(wrong[wi++]); }
  return { ...q, answers: na, correct: tgt };
};

