class SndEng {
  constructor() { this.ctx = null; this.on = true; }
  _init() { if (!this.ctx) try { this.ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e) {} }
  play(t) {
    if (!this.on) return; this._init(); if (!this.ctx) return;
    const m = {
      ok:    [[523,.07],[659,.07],[784,.08],[1047,.22]],
      ko:    [[330,.1],[220,.22]],
      tick:  [[1600,.04]],
      win:   [[523,.06],[659,.06],[784,.06],[1047,.07],[1319,.38]],
      badge: [[784,.06],[1047,.06],[1319,.07],[1568,.42]],
      start: [[392,.12],[523,.12],[659,.14]],
    };
    let ts = this.ctx.currentTime;
    (m[t] || []).forEach(([freq, dur]) => {
      const o = this.ctx.createOscillator(), g = this.ctx.createGain();
      o.connect(g); g.connect(this.ctx.destination);
      o.type = t === "ko" ? "sawtooth" : "sine"; o.frequency.value = freq;
      g.gain.setValueAtTime(.22, ts); g.gain.exponentialRampToValueAtTime(.001, ts + dur);
      o.start(ts); o.stop(ts + dur + .01); ts += dur;
    });
  }
}
const SND = new SndEng();

// ── WEB SPEECH API ──────────────────────────────────────────────
// SpeechBtn component and speak() utility already defined below
let AUDIO_ON=true; // controlled by Settings

// ── SPEECH (Web Speech API) ──────────────────────────────────────
function SpeechBtn({text,lang,style={}}){
  const[on,setOn]=useState(false);
  const supported=typeof window!=="undefined"&&!!window.speechSynthesis&&AUDIO_ON;
  if(!supported)return null;
  const go=e=>{
    e.stopPropagation();
    if(on){window.speechSynthesis.cancel();setOn(false);return;}
    window.speechSynthesis.cancel();
    // Small delay for Android Chrome
    setTimeout(()=>{
      const u=new SpeechSynthesisUtterance(text);
      u.lang=lang==="en"?"en-GB":"fr-FR";
      u.rate=0.85;u.pitch=1;u.volume=1;
      u.onend=()=>setOn(false);u.onerror=()=>setOn(false);
      setOn(true);
      window.speechSynthesis.speak(u);
    },50);
  };
  return(
    <button onClick={go} title={lang==="en"?"Listen":"Écouter"}
      style={{background:on?"#E8003D":"rgba(232,0,61,.12)",border:`1.5px solid ${on?"#E8003D":"rgba(232,0,61,.25)"}`,borderRadius:22,padding:"6px 12px",cursor:"pointer",display:"inline-flex",alignItems:"center",gap:5,color:on?"white":"#E8003D",fontWeight:800,fontSize:13,flexShrink:0,transition:"all .2s",...style}}>
      <span style={{fontSize:16}}>{on?"⏹":"🔊"}</span>
      <span style={{fontSize:11}}>{on?(lang==="en"?"stop":"stop"):(lang==="en"?"listen":"écouter")}</span>
    </button>
  );
}

