function DefiModal({onClose,lang}){
  const[done,setDone]=useState(()=>localStorage.getItem('hm_defi_last_done')===getTodayKeyR());
  const[streak]=useState(()=>parseInt(localStorage.getItem('hm_defi_streak')||'0',10));

  function getTodayKeyR(){const n=new Date();return `${n.getFullYear()}-${n.getMonth()+1}-${n.getDate()}`;}
  function getDayOfYearR(){const n=new Date();const s=new Date(n.getFullYear(),0,0);return Math.floor((n-s)/86400000);}

  const specialKey=`${new Date().getMonth()+1}-${new Date().getDate()}`;
  const special=SPECIAL_DEFIS_REACT[specialKey];
  const defisPool=lang==="en"?DEFIS_REACT_EN:DEFIS_REACT;
  const defi=special||defisPool[(getDayOfYearR()-1)%defisPool.length];

  function handleDone(){
    if(done)return;
    const today=getTodayKeyR();
    const yesterday=()=>{const d=new Date();d.setDate(d.getDate()-1);return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`;};
    const last=localStorage.getItem('hm_defi_last_done');
    let s=streak;
    if(last===yesterday())s++;else s=1;
    localStorage.setItem('hm_defi_last_done',today);
    localStorage.setItem('hm_defi_streak',String(s));
    setDone(true);
    setTimeout(onClose,1800);
  }

  return(
    <div style={{position:"fixed",inset:0,zIndex:9999,background:"rgba(45,10,31,.72)",backdropFilter:"blur(6px)",display:"flex",alignItems:"flex-end",justifyContent:"center"}} onClick={e=>{if(e.target===e.currentTarget)onClose();}}>
      <div style={{width:"100%",maxWidth:480,background:"#FFF4F7",borderRadius:"28px 28px 0 0",padding:"28px 22px 42px",maxHeight:"92vh",overflowY:"auto"}}>
        <div style={{width:40,height:4,background:"#E8003D33",borderRadius:99,margin:"0 auto 20px"}}/>
        {special&&<div style={{textAlign:"center",marginBottom:14}}>
          <div style={{fontSize:11,fontWeight:800,color:P.red,textTransform:"uppercase",letterSpacing:.5,marginBottom:4}}>{lang==="en"?"🎉 Special Day":"🎉 Jour Spécial"}</div>
          <div style={{fontSize:"1rem",fontWeight:800,color:P.text}}>{special.title}</div>
        </div>}
        {!special&&<div style={{textAlign:"center",marginBottom:14}}>
          <div style={{fontSize:30,marginBottom:4}}>{defi.cat}</div>
          <div style={{fontSize:11,fontWeight:800,color:P.red,textTransform:"uppercase",letterSpacing:.5}}>{lang==="en"?"Daily Challenge 🌸":"Défi du jour 🌸"}</div>
        </div>}
        <div style={{background:"linear-gradient(135deg,#FFF0F5,#FFE8EF)",borderRadius:18,padding:"20px 18px",marginBottom:16,border:"1.5px solid rgba(232,0,61,.12)"}}>
          <div style={{display:"flex",alignItems:"flex-start",gap:10}}>
            <div style={{fontSize:".95rem",color:P.text,lineHeight:1.75,fontWeight:600,flex:1}}>{defi.text}</div>
            <SpeechBtn text={defi.text} lang={lang} style={{marginTop:2}}/>
          </div>
        </div>
        {streak>0&&<div style={{background:"linear-gradient(135deg,#FFE8EF,#FFD6E8)",borderRadius:14,padding:"12px 16px",display:"flex",alignItems:"center",gap:10,marginBottom:16}}>
          <span style={{fontSize:"1.5rem"}}>🔥</span>
          <div>
            <div style={{fontSize:".78rem",fontWeight:700,color:P.red}}>{streak} {lang==="en"?`day${streak>1?"s":""} in a row`:`jour${streak>1?"s":""} de suite`} {streak>=7?"🔥🔥":streak>=3?"🔥":""}</div>
            <div style={{fontSize:".7rem",color:"#7A3D5A",marginTop:2}}>{streak>=7?(lang==="en"?"You keep coming back — that's real dedication.":"Tu reviens. C'est ça la vraie force."):streak>=3?(lang==="en"?"You're building a great habit — keep it up!":"Tu prends l'habitude. Continue."):(lang==="en"?"Here we go — your journey begins today!":"C'est parti. Ta flamme vient de s'allumer.")}</div>
          </div>
        </div>}
        <div style={{display:"flex",gap:10}}>
          <button onClick={onClose} style={{flex:1,padding:14,borderRadius:14,border:"2px solid rgba(232,0,61,.2)",background:"white",color:"#B33",fontSize:".88rem",fontWeight:700,cursor:"pointer"}}>{lang==="en"?"Later":"Plus tard"}</button>
          <button onClick={handleDone} disabled={done} style={{flex:2,padding:14,borderRadius:14,border:"none",background:done?"linear-gradient(135deg,#7FB069,#52A35D)":"linear-gradient(135deg,#E8003D,#FF6B9D)",color:"white",fontSize:".92rem",fontWeight:800,cursor:done?"default":"pointer",boxShadow:"0 5px 18px rgba(232,0,61,.32)"}}>
            {done?(lang==="en"?"✅ Challenge done today":"✅ Défi fait aujourd'hui"):(lang==="en"?"Challenge done 🌸":"Défi accompli 🌸")}
          </button>
        </div>
      </div>
    </div>
  );
}

function GamePlay({gameId,gameLevel,lang,onBack,onBadge,onComplete}){
  const props={level:gameLevel,lang,onBack,onBadge,onComplete};
  const games={
    g1:<JeuAssocie  key={`g1-${gameLevel}`}  {...props}/>,
    g2:<JeuCorps    key={`g2-${gameLevel}`}  {...props}/>,
    g3:<JeuMemoire  key={`g3-${gameLevel}`}  {...props}/>,
    g4:<JeuChef     key={`g4-${gameLevel}`}  {...props}/>,
    g5:<JeuCycle    key={`g5-${gameLevel}`}  {...props}/>,
    g6:<JeuSOS      key={`g6-${gameLevel}`}  {...props}/>,
    dev:<JeuDevinettes key="dev" onBack={onBack} onBadge={onBadge} lang={lang}/>,
    img:<JeuImages  key={`img-${gameLevel}`} {...props}/>,
    ws:<JeuMotsMeles key={`ws-${gameLevel}`} {...props}/>,
    lab:<JeuLabyrinthe key={`lab-${gameLevel}`} {...props}/>,
  };
  return games[gameId]||null;
}


// ── SPLASH SCREEN ───────────────────────────────────────────────
function SplashScreen({onDone,isReady}){
  const[fading,setFading]=useState(false);
  const startRef=useRef(Date.now());
  const MIN_SHOW=900;   // minimum visible : 900ms
  const FADE_DUR=400;   // fondu : 400ms
  const MAX_TOTAL=1800; // jamais plus de 1.8s

  // Déclencheur unique : ferme dès que l'app est prête ET min atteint, ou au bout de MAX_TOTAL
  useEffect(()=>{
    const hardStop=setTimeout(()=>{setFading(true);setTimeout(onDone,FADE_DUR);},MAX_TOTAL-FADE_DUR);
    return()=>clearTimeout(hardStop);
  },[]);

  useEffect(()=>{
    if(!isReady)return;
    const elapsed=Date.now()-startRef.current;
    const wait=Math.max(0,MIN_SHOW-elapsed);
    const t=setTimeout(()=>{
      setFading(true);
      setTimeout(onDone,FADE_DUR);
    },wait);
    return()=>clearTimeout(t);
  },[isReady]);

  return(
    <div
      className={`splash-screen${fading?" fading":""}`}
      style={{position:"fixed",inset:0,zIndex:9999,margin:0,padding:0,background:"#E8003D",overflow:"hidden",WebkitTapHighlightColor:"transparent"}}
    >
      <img
        src="/splash.jpg"
        alt="Quiz Dignité"
        style={{display:"block",width:"100vw",height:"100dvh",minHeight:"100vh",objectFit:"cover",objectPosition:"center center",margin:0,padding:0,border:"none",maxWidth:"none",maxHeight:"none",WebkitUserSelect:"none",userSelect:"none"}}
        draggable={false}
      />
    </div>
  );
}

